From aa105d231a36422314335fabe35254a07544d26b Mon Sep 17 00:00:00 2001
From: Johan Malm <jgm323@gmail.com>
Date: Fri, 14 Apr 2017 18:48:58 +0100
Subject: [PATCH] jgmenu.c: fixed bug introduced by aa1357d3


diff --git a/jgmenu.c b/jgmenu.c
index f918f91..f008f0f 100644
--- a/jgmenu.c
+++ b/jgmenu.c
@@ -969,11 +969,11 @@ void create_node(const char *name, struct node *parent)
 	if (!name)
 		die("cannot create node without name");
 	n->tag = strdup(name);
-	if (tag_exists(name))
-		n->item = get_item_from_tag(name);
-	else
+	if (!strcmp(name, "__root__"))
 		n->item = list_first_entry_or_null(&menu.master,
 						   struct item, master);
+	else
+		n->item = get_item_from_tag(name);
 	n->last_sel = NULL;
 	n->parent = parent;
 	INIT_LIST_HEAD(&n->items);
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was likely caused by the incorrect handling of the special case for the node name `"__root__"`, which was not being explicitly checked in the original logic. This could lead to unexpected behavior when trying to create a root node, as it would not retrieve the correct item from the master list, potentially resulting in a null or incorrect item assignment.

        Commit message:
        jgmenu.c: fixed bug introduced by aa1357d3  

        Patch:

 void create_node(const char *name, struct node *parent)
 {
 	struct node *n;

 	n = xmalloc(sizeof(struct node));
 	if (!name)
 		die("cannot create node without name");
 	n->tag = strdup(name);
-	if (tag_exists(name))
-		n->item = get_item_from_tag(name);
-	else
+	if (!strcmp(name, "__root__"))
 		n->item = list_first_entry_or_null(&menu.master,
 						   struct item, master);
+	else
+		n->item = get_item_from_tag(name);
 	n->last_sel = NULL;
 	n->parent = parent;
 	INIT_LIST_HEAD(&n->items);
 	list_add_tail(&n->node, &menu.nodes);
 }



